"""Read the five SVGs generated by the pinned Profile Summary Cards action.

The upstream charts use D3 scales. Their tick positions, slice angles and data
vertices expose the same values used to render the published charts.
"""

from dataclasses import dataclass
from datetime import date
import math
from pathlib import Path
import re
import xml.etree.ElementTree as ET


NS = {"s": "http://www.w3.org/2000/svg"}
NUMBER = r"-?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
TRANSLATE_Y = re.compile(rf"translate\(0,\s*({NUMBER})\)")
FIRST_ARC = re.compile(
    rf"^M({NUMBER}),({NUMBER})A{NUMBER},{NUMBER},0,[01],1,({NUMBER}),({NUMBER})"
)


@dataclass(frozen=True)
class Snapshot:
    totals: tuple[str, str, str]
    monthly: tuple[tuple[date, int], ...]
    hourly: tuple[int, ...]
    by_repo: tuple[tuple[str, float], ...]
    by_commit: tuple[tuple[str, float], ...]


def labels(svg: ET.Element) -> list[str]:
    return ["".join(node.itertext()).strip() for node in svg.findall(".//s:text", NS)]


def total(stats: ET.Element, label: str) -> str:
    text = labels(stats)
    metrics = [item for item in text if item.startswith("Total ") or item == "Contributed to:"]
    values = [item for item in text if re.fullmatch(r"\d+(?:\.\d+)?[kKmMbB]?", item)]
    if len(metrics) != len(values) or label not in metrics:
        raise ValueError(f"Unexpected stats card while reading {label}")
    return dict(zip(metrics, values, strict=True))[label]


def y_axis(svg: ET.Element) -> tuple[float, float]:
    ticks = {}
    for tick in svg.findall(".//s:g[@class='tick']", NS):
        offset = TRANSLATE_Y.fullmatch(tick.get("transform", ""))
        label = tick.find("s:text", NS)
        if offset is not None and label is not None:
            value = (label.text or "").replace(",", "")
            if value.isdigit():
                ticks[int(value)] = float(offset[1])
    if 0 not in ticks or len(ticks) < 2:
        raise ValueError("Missing numeric y-axis ticks")
    highest = max(ticks)
    baseline = ticks[0]
    # D3's axis is shifted half a pixel to align its strokes.
    return baseline - 0.5, highest / (baseline - ticks[highest])


def monthly_counts(svg: ET.Element) -> tuple[tuple[date, int], ...]:
    month_ticks = [item for item in labels(svg) if re.fullmatch(r"\d{2}/\d{2}", item)]
    areas = [
        node.get("d", "")
        for node in svg.findall(".//s:path", NS)
        if node.get("transform") == "translate(-30,0)" and node.get("d", "").startswith("M0,")
    ]
    if not month_ticks or len(areas) != 1:
        raise ValueError("Missing dates or area path in the contribution chart")
    upper_curve = areas[0].split("L", 1)[0]
    # The endpoints of D3's monotone cubic segments are the monthly samples.
    vertices = [float(command.rsplit(",", 1)[-1]) for command in re.findall(r"[MC]([^MCZ]+)", upper_curve)]
    if len(vertices) not in (12, 13):
        raise ValueError("Unexpected number of monthly samples")
    year, month = map(int, month_ticks[0].split("/"))
    first_month = (2000 + year) * 12 + month - 1
    baseline, units_per_pixel = y_axis(svg)
    return tuple(
        (
            date((first_month + index) // 12, (first_month + index) % 12 + 1, 1),
            max(0, round((baseline - height) * units_per_pixel)),
        )
        for index, height in enumerate(vertices)
    )


def local_hours(svg: ET.Element) -> tuple[int, ...]:
    heights = [float(bar.attrib["height"]) for bar in svg.findall(".//s:rect[@class='bar']", NS)]
    if len(heights) != 24 or not any(re.fullmatch(r"Commits \(UTC \+?0(?:\.00)?\)", s) for s in labels(svg)):
        raise ValueError("Expected 24 hourly bars in UTC")
    if not any(heights):
        return (0,) * 24
    _, units_per_pixel = y_axis(svg)
    utc = [round(height * units_per_pixel) for height in heights]
    # The upstream sample remains in UTC. Display those same buckets in UTC+8.
    return tuple(utc[-8:] + utc[:-8])


def language_shares(svg: ET.Element) -> tuple[tuple[str, float], ...]:
    legend = svg.findall(".//s:g[@transform='translate(40,0)']/s:text", NS)
    names = [node.text for node in legend if node.text]
    wedges = svg.findall(".//s:g[@class='arc']/s:path", NS)
    if not names or len(names) != len(wedges) or len(names) > 5:
        raise ValueError("Missing or mismatched data in the language card")
    if len(names) == 1:
        return ((names[0], 1.0),)

    shares = []
    for name, wedge in zip(names, wedges, strict=True):
        match = FIRST_ARC.match(wedge.get("d", ""))
        if match is None:
            raise ValueError(f"Unexpected slice geometry for {name}")
        x1, y1, x2, y2 = map(float, match.groups())
        start, end = math.atan2(y1, x1), math.atan2(y2, x2)
        shares.append((name, (end - start) % math.tau / math.tau))
    if not math.isclose(sum(share for _, share in shares), 1, abs_tol=1e-6):
        raise ValueError("Language slices do not form a full circle")
    return tuple(shares)


def read_snapshot(source: Path) -> Snapshot:
    details = ET.parse(source / "0-profile-details.svg").getroot()
    stats = ET.parse(source / "3-stats.svg").getroot()
    by_repo = ET.parse(source / "1-repos-per-language.svg").getroot()
    by_commit = ET.parse(source / "2-most-commit-language.svg").getroot()
    hours = ET.parse(source / "4-productive-time.svg").getroot()
    contributions = next(
        (match[1] for text in labels(details)
         if (match := re.fullmatch(r"(\d+(?:\.\d+)?[kKmMbB]?) Contributions on GitHub", text))),
        None,
    )
    if contributions is None:
        raise ValueError("Missing total contributions in the profile details card")

    return Snapshot(
        totals=(total(stats, "Total Commits:"), total(stats, "Total PRs:"), contributions),
        monthly=monthly_counts(details),
        hourly=local_hours(hours),
        by_repo=language_shares(by_repo),
        by_commit=language_shares(by_commit),
    )
